/* builds a basis from a direction vector and writes the orientation into the moby */
void set_batalia_bolt_pickup_surface_rotation(char *a, float *v) {
    float m[16];
    float n[16];
    float r[4];
    float s[4];
    char *d = ((char *)((Moby *)a)->pvars);
    r[1] = v[2];
    r[2] = v[0];
    r[0] = -v[1];
    FastVecCross(r, v, r);
    FastVecCross(s, r, v);
    qcopy(m, r);
    qcopy(m + 4, s);
    qcopy(m + 8, v);
    clear_u64_value(m + 12);
    d += 0x10;
    m[15] = 1.0f;
    matrix_to_euler(m, d);
    euler_to_matrix(n, (float *)d);
    n[15] = 42.0f;
}
