/* aims a turret: builds its barrel frame from the base rotation, yaw and pitch, writes the barrel rotation
 * and the muzzle point (offset per turret class) */
void compute_batalia_bolt_pickup_surface_pose(char *m, float *out, float *rot) {
    float r[16];
    float b[16];
    float up[4];
    float side[4];
    float fwd[4];
    float dir[4];
    float u[4];
    float v[4];
    struct Vars_4BE8 *d = (struct Vars_4BE8 *)((Moby *)m)->pvars;
    float sx, sy, sz;
    float t;
    switch (((Moby *)m)->oclass) {
    case 0x3DC:
        sx = *(float *)&batalia_bolt5_tilt_deg * *(float *)&batalia_bolt5_scale;
        sy = *(float *)&batalia_bolt5_lift * *(float *)&batalia_bolt5_scale;
        sz = *(float *)&batalia_bolt5_forward_offset * *(float *)&batalia_bolt5_scale;
        break;
    case 0x3DD:
        sx = *(float *)&batalia_bolt10_tilt_deg * *(float *)&batalia_bolt10_scale;
        sy = *(float *)&batalia_bolt10_lift * *(float *)&batalia_bolt10_scale;
        sz = *(float *)&batalia_bolt10_forward_offset * *(float *)&batalia_bolt10_scale;
        break;
    default:
        sx = *(float *)&batalia_bolt_tilt_deg * *(float *)&batalia_bolt_scale;
        sy = *(float *)&batalia_bolt_lift * *(float *)&batalia_bolt_scale;
        sz = *(float *)&batalia_bolt_forward_offset * *(float *)&batalia_bolt_scale;
        break;
    }
    euler_to_matrix(b, &d->v10[0]);
    vec_scale_to_length(u, b, -FastSin(d->f60));
    vec_scale_to_length(v, b + 4, FastCos(d->f60));
    FastVecAdd(dir, u, v);
    t = sx * 0.017453292f;
    vec_scale_to_length(u, dir, FastCos(t));
    vec_scale_to_length(v, b + 8, FastSin(t));
    FastVecAdd(up, u, v);
    vec_scale_to_length(u, b, -FastCos(d->f60));
    vec_scale_to_length(v, b + 4, -FastSin(d->f60));
    FastVecAdd(fwd, u, v);
    FastVecCross(side, up, fwd);
    vec_scale_to_length(u, side, FastCos(d->f64));
    vec_scale_to_length(v, fwd, FastSin(d->f64));
    FastVecAdd(r, u, v);
    vec_scale_to_length(u, side, -FastSin(d->f64));
    vec_scale_to_length(v, fwd, FastCos(d->f64));
    FastVecAdd(r + 4, u, v);
    qcopy(r + 8, up);
    r[11] = 0.0f;
    clear_u64_value(r + 12);
    r[15] = 1.0f;
    matrix_to_euler(r, rot);
    rot[3] = 0.0f;
    vec_scale_to_length(u, b + 8, sy);
    FastVecAdd(out, d->v0, u);
    vec_scale_to_length(v, dir, sz);
    FastVecAdd(out, out, v);
}
