/* Checks the 13 object slots at data + 0x60 (stride 16) with func_L00_0025B478(slot, 0x10000, 0). Each hit adds to a
 * counter by slot index (1, 2, or 4 for slots 5 and up) and sets the slot's byte at +0xA4 to 0xFF. The counter is added
 * to the short at data + 0x13C; when that reaches 8 it is taken mod 8 and one slot object is released (its state byte
 * set to 1, the slot cleared), or the moby's state becomes 0x63 if none is left. */
void process_shrub_part_hits(char *m) {
    char *data = ((char *)((Moby *)m)->pvars);
    char *base = (char *)((struct ShrubVars *)data)->slots;
    char **p = (char **)base;
    char **sq;
    int n = 0;
    int idx = 0;
    int r = -1;
    int i;
    for (i = 0; i < 13; i++, p += 4) {
        if (*p != 0) {
            if (MobyGetHitMessage(*p, 0x10000, 0) != 0) {
                if (i < 3) {
                    if (n <= 0) { n = 1; r = 1; }
                } else if (i < 5) {
                    if (n < 2) { n = 2; r = 1; }
                } else {
                    if (n < 4) { n += 4; idx = i; r = 2; }
                }
                ((unsigned char *)*p)[0xA4] = 0xFF;
            }
        }
    }
    *(unsigned short *)&((struct ShrubVars *)data)->hit_count += n;
    if (((struct ShrubVars *)data)->hit_count >= 8) {
        ((struct ShrubVars *)data)->hit_count = ((struct ShrubVars *)data)->hit_count % 8;
        if (idx != 0) {
            int o1 = idx * 16;
            char **q = (char **)(base + o1);
            char *t = *q;
            char *d2;
            d2 = ((char *)((Moby *)t)->pvars);
            SpawnExplosionFx(m, t + 0x10, -1, 2.0f, 13.0f);
            FastVecSub(d2, *q + 0x10, *(char **)(o1 + data + 0x64) + 0x10);
            vec_scale_to_length(d2, d2, g_frame_time * 10.0f);
            (*q)[0x20] = 1;
            *q = 0;
            return;
        } else {
            int s = truncate_float_to_s32(random_float_between(0.0f, 23.0f));
                        char *b2 = base;
            for (i = 0; i < 8; i++) {
                int k = (i + s) % 8 + 5;
                int off = k * 16;
                base = b2 + off; sq = (char **)base;
                if (*sq != 0) {
                    char *d2 = *(char **)(*sq + 0x78);
                    SpawnExplosionFx(m, *sq + 0x10, -1, 2.0f, 13.0f);
                    FastVecSub(d2, *sq + 0x10, *(char **)(data + off + 0x64) + 0x10);
                    vec_scale_to_length(d2, d2, g_frame_time * 10.0f);
                    (*sq)[0x20] = 1;
                    *sq = 0;
                    return;
                }
            }
            m[0x20] = 0x63;
        }
    }
    if (r >= 0) Moby_PlaySound_r(r, 0, (int)m);
}
